		if (sel_b2)
			out_always = b;
		else
			out_always = a;
	end

endmodule

	wire [2:0] w;
	wire [2:0] w_next;

	assign w_next[0] = (w[0] & ~w[1]) | (w[2] & ~w[1]);
	assign w_next[1] = (w[0] & w[1]) | (w[2] & w[1]);
	assign w_next[2] = w[2] ^ w[1];

	always @(posedge clk) begin
		if (enable) begin
			w[0] <= S;
			w[1] <= A;
			w[2] <= B;
		end
		else begin
			w[0] <= w_next[0];
			w[1] <= w_next[1];
			w[2] <= w_next[2];
		end
	end

	assign Z = w[2] ^ w[1];

endmodule

