	reg [1:0] state;
	parameter S0 = 2'b00;
	parameter S1 = 2'b01;
	parameter S2 = 2'b10;
	parameter S3 = 2'b11;

	always @(posedge clk or negedge aresetn) begin
		if (!aresetn) begin
			state <= S0;
			z <= 1'b0;
		end
		else begin
			case (state)
				S0: begin
					if (x) begin
						state <= S1;
						z <= 1'b0;
					end
					else begin
						state <= S0;
						z <= 1'b0;
					end
				end
				S1: begin
					if (x) begin
						state <= S2;
						z <= 1'b0;
					end
					else begin
						state <= S0;
						z <= 1'b0;
					end
				end
				S2: begin
					if (x) begin
						state <= S2;
						z <= 1'b0;
					end
					else begin
						state <= S3;
						z <= 1'b1;
					end
				end
				S3: begin
					if (x) begin
						state <= S2;
						z <= 1'b0;
					end
					else begin
						state <= S0;
						z <= 1'b0;
					end
				end
				default: begin
					state <= S0;
					z <= 1'b0;
				end
			endcase
		end
	end

endmodule

	wire [1:0] state;
	wire [1:0] next_state;

	assign next_state = state == 2'b00 ? (in ? 2'b01 : 2'b00) :
	                    state == 2'b01 ? (in ? 2'b11 : 2'b00) :
	                    state == 2'b11 ? (in ? 2'b11 : 2'b10) :
	                    state == 2'b10 ? (in ? 2'b01 : 2'b00) : 2'b00;

	assign out = state == 2'b11;

	always @(posedge clk) begin
		if (reset)
			state <= 2'b00;
		else
			state <= next_state;
	end

endmodule

	wire [1:0] w;
